**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
using namespace std;

int main() {
    ifstream plik("dane.txt");
    int tab[5][6];
    for (int i = 0; i < 5; i++)
        for (int j = 0; j < 6; j++)
            plik >> tab[i][j];

    int sumy[5];
    for (int i = 0; i < 5; i++) {
        sumy[i] = 0;
        for (int j = 0; j < 6; j++)
            sumy[i] += tab[i][j];
    }

    cout << "a) Sumy wierszy:";
    for (int i = 0; i < 5; i++)
        cout << " " << sumy[i];
    cout << endl;

    int maxIdx = 0;
    for (int i = 1; i < 5; i++)
        if (sumy[i] > sumy[maxIdx])
            maxIdx = i;
    cout << "b) Wiersz z max suma: " << maxIdx + 1 << endl;
    return 0;
}
```

**Wyjasnienie**: Sumujemy elementy kazdego wiersza, potem szukamy indeksu wiersza z najwyzsza suma.

Weryfikacja:
- Wiersz 1: 3+1+4+1+5+9 = 23
- Wiersz 2: 2+6+5+3+5+8 = 29
- Wiersz 3: 9+7+9+3+2+3 = 33
- Wiersz 4: 8+4+6+2+6+4 = 30
- Wiersz 5: 3+2+7+9+5+0 = 26
Max: wiersz 3 (suma 33).
